function GardenCompostSifterDrumMaker.init() GardenCompostSifterDrumMaker.ironStock=14; GardenCompostSifterDrumMaker.bronzeStock=12; GardenCompostSifterDrumMaker.woodStock=14; GardenCompostSifterDrumMaker.leatherStock=8; GardenCompostSifterDrumMaker.silverStock=8; GardenCompostSifterDrumMaker.goldStock=6; GardenCompostSifterDrumMaker.jewelStock=4; GardenCompostSifterDrumMaker.pearlStock=4; GardenCompostSifterDrumMaker.productStock={}; GardenCompostSifterDrumMaker.buildings={}; GardenCompostSifterDrumMaker.maker=nil; GardenCompostSifterDrumMaker.activeMaking={}; GardenCompostSifterDrumMaker.totalProducts=0; GardenCompostSifterDrumMaker.dayTimer=0; print("[GardenCompostSifterDrumMaker] Royal Garden Compost Sifter Drum Maker System initialized (6 products, 4 buildings)") end
function GardenCompostSifterDrumMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenCompostSifterDrumMaker.maker={name=n or ("Bobnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bobnar najet: %s (spretnost: %d)",GardenCompostSifterDrumMaker.maker.name,s),"success") end; return true end
function GardenCompostSifterDrumMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenCompostSifterDrumMaker.build(id) local ok,e=GardenCompostSifterDrumMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenCompostSifterDrumMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenCompostSifterDrumMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenCompostSifterDrumMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenCompostSifterDrumMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenCompostSifterDrumMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenCompostSifterDrumMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenCompostSifterDrumMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenCompostSifterDrumMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenCompostSifterDrumMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenCompostSifterDrumMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenCompostSifterDrumMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenCompostSifterDrumMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenCompostSifterDrumMaker.buildings==0 then return false,"Potrebna bobnarska delavnica" end; if not GardenCompostSifterDrumMaker.maker then return false,"Potreben bobnar" end; return true end
function GardenCompostSifterDrumMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenCompostSifterDrumMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenCompostSifterDrumMaker.ironStock=GardenCompostSifterDrumMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenCompostSifterDrumMaker.bronzeStock=GardenCompostSifterDrumMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenCompostSifterDrumMaker.woodStock=GardenCompostSifterDrumMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenCompostSifterDrumMaker.leatherStock=GardenCompostSifterDrumMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenCompostSifterDrumMaker.silverStock=GardenCompostSifterDrumMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenCompostSifterDrumMaker.goldStock=GardenCompostSifterDrumMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenCompostSifterDrumMaker.jewelStock=GardenCompostSifterDrumMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenCompostSifterDrumMaker.pearlStock=GardenCompostSifterDrumMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenCompostSifterDrumMaker.maker then t=math.max(1,t-math.floor(GardenCompostSifterDrumMaker.maker.skill/13)) end; table.insert(GardenCompostSifterDrumMaker.activeMaking,{id="gardencompostsifterdrum_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenCompostSifterDrumMaker.completeMaking(m) local q=1.0+(GardenCompostSifterDrumMaker.getQualityBonus()/100); if GardenCompostSifterDrumMaker.maker then q=q+(GardenCompostSifterDrumMaker.maker.skill/140) end; q=math.min(2.5,q); GardenCompostSifterDrumMaker.productStock[m.productType]=(GardenCompostSifterDrumMaker.productStock[m.productType] or 0)+m.quantity; GardenCompostSifterDrumMaker.totalProducts=GardenCompostSifterDrumMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenCompostSifterDrumMaker.maker then GardenCompostSifterDrumMaker.maker.itemsMade=GardenCompostSifterDrumMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenCompostSifterDrumMaker.maker.skill=math.min(100,GardenCompostSifterDrumMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Boben izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardencompostsifterdrum.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenCompostSifterDrumMaker.update(dt) if not _G.state then return end; GardenCompostSifterDrumMaker.dayTimer=GardenCompostSifterDrumMaker.dayTimer+dt; if GardenCompostSifterDrumMaker.dayTimer>=30 then GardenCompostSifterDrumMaker.dayTimer=0; for i=#GardenCompostSifterDrumMaker.activeMaking,1,-1 do local m=GardenCompostSifterDrumMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenCompostSifterDrumMaker.completeMaking(m); table.remove(GardenCompostSifterDrumMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenCompostSifterDrumMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenCompostSifterDrumMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenCompostSifterDrumMaker.getStats() return {ironStock=GardenCompostSifterDrumMaker.ironStock,bronzeStock=GardenCompostSifterDrumMaker.bronzeStock,woodStock=GardenCompostSifterDrumMaker.woodStock,leatherStock=GardenCompostSifterDrumMaker.leatherStock,silverStock=GardenCompostSifterDrumMaker.silverStock,goldStock=GardenCompostSifterDrumMaker.goldStock,jewelStock=GardenCompostSifterDrumMaker.jewelStock,pearlStock=GardenCompostSifterDrumMaker.pearlStock,productStock=GardenCompostSifterDrumMaker.productStock,numBuildings=#GardenCompostSifterDrumMaker.buildings,hasMaker=GardenCompostSifterDrumMaker.maker~=nil,makerName=GardenCompostSifterDrumMaker.maker and GardenCompostSifterDrumMaker.maker.name or "—",makerSkill=GardenCompostSifterDrumMaker.maker and GardenCompostSifterDrumMaker.maker.skill or 0,activeMaking=#GardenCompostSifterDrumMaker.activeMaking,totalProducts=GardenCompostSifterDrumMaker.totalProducts} end
